// The Convergence: local, illustrative formations rather than live-set advice.
function convergenceMark(kind='world') {
  const shapes={world:'M20 8 32 15v14L20 36 8 29V15ZM8 15l12 7 12-7M20 22v14M20 2v3M3 12l3 2m28 0 3-2',comps:'M8 8h17v24H8ZM14 4h18v23M13 16l3-4 3 4-3 4ZM12 24h9',planner:'m10 7 8 5v9l-8 5-8-5v-9Zm18 0 8 5v9l-8 5-8-5ZM19 23l8 5v9l-8 5-8-5v-9',history:'M9 5h22v29H9ZM5 9v29h23M15 13h10M15 19h10M15 25h6'};
  return `<svg class="convergence-mark" viewBox="0 0 40 44" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="${shapes[kind]}"/></svg>`;
}
function tftNavigation(page){return `<nav class="tft-navigation" aria-label="TFT navigation"><a class="tft-lockup" href="#/tft" aria-label="Teamfight Tactics overview">${convergenceMark()}<span>TEAMFIGHT<small>TACTICS</small></span></a><div class="tft-menu">${[['','The Convergence','world'],['comps','Team comps','comps'],['planner','Board planner','planner'],['history','Match history','history']].map(([p,label,glyph])=>`<a href="#/tft${p?'/'+p:''}" ${page===p?'aria-current="page"':''}>${convergenceMark(glyph)}<span>${label}</span></a>`).join('')}</div><a class="tft-nav-plan" href="#/tft/planner">${icon(formations[state.plan].carry)}<span>Your strategy table<strong>${formations[state.plan].name}</strong></span></a></nav>`;}
function tftWorldOverview(){const f=formations[state.plan],r=tftMatches.find(m=>m.plan===state.plan);return `${tftNavigation('')}<section class="convergence-arrival"><div class="convergence-party" aria-hidden="true"></div><div class="convergence-welcome"><span class="tft-whisper">A seat at the Convergence</span><h1>A little wonder.<br>A clever plan.</h1><p>Find an unlikely team. Make a little room for magic.<br>Your next great board starts here.</p>${link('#/tft/comps','Find your next team','action')}<span class="welcome-postscript">Good company. Beautiful chaos.</span></div><div class="arrival-ticket">${convergenceMark()}<span>Eight tacticians.<br>A world of possibilities.</span></div></section>
  <section class="tft-table-invitation"><div class="table-invitation-copy"><span class="tft-whisper">Waiting at your strategy table</span><h2>${f.name}</h2><p>${f.line}</p><div class="invitation-carry">${icon(f.carry)}<span>Built around <strong>${units[f.carry]}</strong></span></div>${link('#/tft/planner','Continue your board','text-link')}<small>${state.savedComps.includes(state.plan)?'Saved in your collection':'Your board is remembered on this device'}</small></div><a class="table-preview" href="#/tft/planner" aria-label="Open your ${f.name} board"><span class="table-engraving">${convergenceMark('planner')}<span>Your next possibility</span></span>${boardMarkup()}<span class="table-preview-link">Take your seat <b>↗</b></span></a></section>
  <section class="convergence-paths"><a href="#/tft/comps"><span class="path-symbol">${convergenceMark('comps')}</span><div><span>Browse the collection</span><h2>Start with a spark.</h2><p>Three team studies to make your own.</p><b>Explore team comps ↗</b></div></a><a href="#/tft/history/${r.id}" class="path-memory"><span class="path-placement">${r.place}</span><div><span>From your journal · Sample</span><h2>${r.line}</h2><p>${f.name}</p><b>Revisit the board ↗</b></div></a></section><p class="tft-world-note">There is always another way to play it.</p>`;}
function tftCollection(){return `${tftNavigation('comps')}${pageHead('The tactician’s collection','Every team starts with a spark.','Pick an idea. Move a few pieces. See what it becomes.')}<section class="tft-folios">${formations.map((f,i)=>`<article class="tft-folio folio-${i}"><div class="folio-portrait" style="--champ-art:url('assets/${f.carry}.webp')"><span class="folio-motif">${convergenceMark(['world','planner','comps'][i])}</span><div><small>A team around</small><h2>${units[f.carry]}</h2><span>${f.tag}</span></div></div><div class="folio-paper"><span class="folio-tab">${['A little space','A sturdy beginning','A pocket of possibility'][i]}</span><h3>${f.name}</h3><p>${f.text}</p><div class="study-roster">${Object.values(f.board).map(u=>`<span>${icon(u)}<small>${units[u]}</small></span>`).join('')}</div><button class="action" data-plan="${i}">Make it your own <span>↗</span></button><small class="folio-status">${state.savedComps.includes(i)?'Saved in your collection':'7 units · Illustrative formation'}</small></div></article>`).join('')}</section><section class="quiet-note">${convergenceMark()}<div><h3>The best plan leaves room for a surprise.</h3><p>These studies explore positioning and team-building. They are independent of any live TFT set.</p></div></section>`;}
